class TestHeaderChaos:
    """Adversarial mutation testing for resilience verification."""

    def test_rapid_status_flapping(self):
        """50 rapid status changes must not corrupt component state."""
        render_header(title="Flap", status="Operational")
        statuses = ["Operational", "Degraded", "Offline", "Maintenance"] * 13
        for status in statuses:
            fire_event.update(screen.container, {"status": status})
        final_indicator = screen.container.query_selector("div.w-4.h-4.rounded-full")
        assert final_indicator is not None

    def test_concurrent_prop_updates(self):
        """Simultaneous title+status updates must apply atomically."""
        render_header(title="Old", status="Operational")
        fire_event.update(screen.container, {"title": "New", "status": "Offline"})
        heading = screen.get_by_role("heading", {"level": 1})
        assert heading.text_content == "New"
        assert screen.get_by_text("Offline") is not None

    def test_memory_does_not_leak_across_renders(self):
        """Repeated unmount/remount cycles must not accumulate listeners."""
        import gc
        for _ in range(100):
            render_header(title="Cycle", status="Operational")
            screen.unmount()
        gc.collect()
        # If listeners leak, this would raise or hang in real environment
        assert True

    def test_random_prop_mutation_sequence(self):
        """Randomized prop mutations must never produce invalid DOM state."""
        random.seed(42)
        render_header(title="Base", status="Operational")
        for _ in range(200):
            mutation = random.choice(["title", "status", "both", "none"])
            if mutation == "title":
                fire_event.update(screen.container, {"title": f"T{random.randint(0, 999)}"})
            elif mutation == "status":
                fire_event.update(screen.container, {"status": random.choice(
                    ["Operational", "Degraded", "Offline", "Maintenance", "Bogus"]
                )})
            elif mutation == "both":
                fire_event.update(screen.container, {
                    "title": f"T{random.randint(0, 999)}",
                    "status": random.choice(["Operational", "Degraded", "Offline", "Maintenance", "Bogus"])
                })
            # Validate invariant: exactly one heading, one indicator
            headings = screen.container.query_selector_all("h1")
            indicators = screen.container.query_selector_all("div.w-4.h-4.rounded-full")
            assert len(headings) == 1
            assert len(indicators) == 1


